from math import isqrt
def sieve_pi(x):
    s=[True]*(x+1); s[0]=s[1]=False
    for p in range(2,isqrt(x)+1):
        if s[p]:
            for k in range(p*p,x+1,p): s[k]=False
    return sum(s)
def compressed(x):
    V=isqrt(x)
    small=[max(v-1,0) for v in range(V+1)]      # small[v]=S(v)
    large=[(x//(e+1))-1 for e in range(V)]       # large[e]=S(x//(e+1))
    for p in range(2,V+1):
        if small[p]-small[p-1]>0:               # p prime
            sp=small[p-1]; p2=p*p
            ns=small[:]; nl=large[:]
            for v in range(p2,V+1):
                ns[v]=small[v]-(small[v//p]-sp)
            for e in range(V):
                val=x//(e+1)
                if val>=p2:
                    ep=(e+1)*p
                    if ep<=V:    sval=large[ep-1]      # affine: w=val//p > V is a large key, index ep-1
                    else:        sval=small[val//p]    # trace: w<=V small key
                    nl[e]=large[e]-(sval-sp)
            small,large=ns,nl
    return large[0]
for n in range(6,21):
    x=(1<<n)-1
    a,b=compressed(x),sieve_pi(x)
    print(n,x,a,b,'OK' if a==b else 'MISMATCH')
"
